suspend fun confirm(orderId: String): String = coroutineScope {
    val address = async(Dispatchers.IO) { customers.address(orderId) }   // both start now
    val cooking = async(Dispatchers.IO) { kitchen.cookTime(orderId) }

    val request = RideRequest(address.await(), cooking.await())
    val ride = riders.book(request).await()      // pauses on the CompletableFuture, holds no thread
    "Your food arrives at ${ride.eta}"
}

